//! Almanac's data model and sync protocol.
//!
//! The server uses these types directly. The clients get them as TypeScript,
//! generated by `bun run gen:types` into `packages/types`.
//!
//! Everything a workspace keeps syncs: its topics, their points, reminders
//! and questions, the talks they were kept from, and its members.
//!
//! On the wire, field names are snake_case, the same as the database columns.

mod account;
mod model;
mod protocol;
mod talk;
mod topic;
mod user;

pub use account::{
    ClaudeKeyInfo, Me, MemberInfo, Role, SetClaudeKeyRequest, UpdateMemberRequest,
    UpdateProfileRequest, UpdateWorkspaceRequest, UserInfo, WorkspaceInfo, clean_name,
    normalize_email, url_key_from,
};
pub use model::{Actor, ModelKind, Validate, ValidationError, Write};
pub use protocol::{
    ApiError, Bootstrap, Operation, ServerMessage, SyncAction, SyncEntry, Transaction,
    TransactionResult,
};
pub use talk::{
    AskRequest, Message, MessageCreate, MessagePatch, Source, Talk, TalkCreate, TalkPatch,
};
pub use topic::{
    ICONS, Point, PointCreate, PointPatch, Question, QuestionCreate, QuestionPatch, Reminder,
    ReminderCreate, ReminderPatch, SHAPES, StartTopicRequest, StartedTopic, Topic, TopicCreate,
    TopicPatch,
};
pub use user::User;
